from gk_b import G,g
GEO="Geography"
PHY="Physical Geography"; IND="Indian Geography"
g(101,"Consider the following States:\nI. Tripura\nII. Chhattisgarh\nIII. Assam\nIV. Odisha\nHow many of the States given above have jute mills?",["One","Two","Three","All four"],"D",GEO,"Economic Geography","Industrial Geography","Distribution of jute mills","Statement Count","M","Beyond West Bengal, jute mills operate in several states: Tripura (1), Chhattisgarh (2), Assam (2) and Odisha (1 to 3) per Ministry of Textiles replies in Parliament.\nAll four states have jute mills.\nAnswer: (d)")
g(102,"Which one of the following is classified under the physical processes of weathering?",["Water pressure","Oxidation","Carbonation","Hydration"],"A",GEO,PHY,"Geomorphology & Earth Surface Processes","Physical versus chemical weathering","Single MCQ","Oxidation, carbonation and hydration are chemical weathering processes.\nPressure from water (for example freezing in cracks and other pressure release) acts mechanically, so it is the physical process listed.\nAnswer: (a)")
g(103,"Consider the following statements:\nI. The Steppes of Eurasia are temperate grasslands.\nII. The Pampas of South America are classified as tropical grasslands.\nWhich of the statements given above is/are correct?",["I only","II only","Both I and II","Neither I nor II"],"A",GEO,PHY,"Biogeography","Temperate grasslands of the world","2-Statement Combination","I: the Eurasian Steppes are temperate grasslands (true).\nII: the Pampas of Argentina and Uruguay are also temperate grasslands, not tropical (false).\nAnswer: (a)")
g(104,"Consider the following statements regarding the slash-and-burn agricultural practices in India:\nI. This practice is a primitive subsistence farming.\nII. This practice is known as Jhum in the North Eastern Hill region.\nIII. When soil fertility decreases, farmers shift to a fresh patch of land.\nWhich of the statements given above is/are correct?",["I only","III only","I and III only","I, II and III"],"D",GEO,IND,"Agriculture & Crops","Shifting cultivation in India","3-Statement Combination","Slash-and-burn (shifting) cultivation is primitive subsistence farming (I), called Jhum in the north-eastern hills (II), and farmers move to fresh land when fertility drops (III).\nAnswer: (d)")
g(105,"Consider the following statements regarding western disturbances in the Indian climate:\nI. These are shallow cyclonic depressions.\nII. They originate over the Caspian Sea and travel to India.\nWhich of the statements given above is/are correct?",["I only","II only","Both I and II","Neither I nor II"],"A",GEO,IND,"Indian Climate","Western disturbances","2-Statement Combination","I: western disturbances are shallow cyclonic depressions (true).\nII: standard texts say they originate over the Mediterranean Sea and travel eastwards, so the Caspian origin is taken as incorrect.\nAnswer: (a)")
g(106,"Consider the following statements regarding earthquake waves:\nI. P-waves are similar to sound waves.\nII. S-waves can travel through gaseous, liquid and solid materials.\nIII. The zone between 105° and 145° from the epicentre is identified as the shadow zone for both P- and S-waves.\nWhich of the statements given above are correct?",["I and II only","II and III only","I and III only","I, II and III"],"C",GEO,PHY,"Earth Interior & Geotectonics","Seismic waves and shadow zones","3-Statement Combination","I: P-waves are longitudinal like sound waves (true).\nII: S-waves cannot pass through liquids or gases (false).\nIII: between 105° and 145° neither P- nor S-waves are recorded (true).\nAnswer: (c)")
g(107,"Consider the following statements:\nI. At the equator, the Coriolis force is zero and here the winds blow perpendicular to the isobars.\nII. The Coriolis force is directly proportional to the angle of latitude.\nIII. The Coriolis force and the resultant wind do not blow parallel to the isobars at higher latitudes.\nWhich of the statements given above are correct?",["I, II and III","II and III only","I and III only","I and II only"],"D",GEO,PHY,"Atmospheric Circulation","Coriolis force and wind direction","3-Statement Combination","I and II follow the standard NCERT statements: the Coriolis force is zero at the equator and increases with latitude, so winds cross the isobars at the equator.\nIII is false: at higher latitudes the wind blows parallel to the isobars (geostrophic wind).\nAnswer: (d)")
g(108,"The Hawaiian volcanoes are the most famous examples of:",["Flood basalt provinces","Calderas","Composite volcanoes","Shield volcanoes"],"D",GEO,PHY,"Geomorphology & Earth Surface Processes","Types of volcanoes","Single MCQ","Hawaiian volcanoes are built by runny basaltic lava that forms broad gentle slopes, the classic shield volcanoes.\nAnswer: (d)")
g(109,"The temperate forests in the Nilgiris, Anaimalai and Palani hills are called:",["Myristica","Kar forest","Devarakadu","Sholas"],"D",GEO,IND,"Indian Vegetation","Montane forests of southern India","Single MCQ","In the higher Western Ghats the temperate (montane) forests are known as Sholas.\nAnswer: (d)")
g(110,"Consider the following statements with regard to igneous rocks:\nI. These rocks cannot be changed into metamorphic rocks.\nII. When molten material is cooled slowly at great depths, mineral grains tend to be very small.\nIII. These rocks are known as primary rocks.\nWhich of the statements given above is/are correct?",["I and II only","III only","II and III only","I, II and III"],"B",GEO,PHY,"Rocks & Minerals","Igneous rocks","3-Statement Combination","I is false: igneous rocks can be metamorphosed.\nII is false: slow cooling at depth gives large grains.\nIII is true: igneous rocks are called primary rocks.\nAnswer: (b)")
g(111,"Consider the following statements:\nI. The Prime Meridian is the same as the International Date Line.\nII. West of the International Date Line is always a day later than east of the line.\nIII. The Earth turns 15° of longitude in an hour.\nWhich of the statements given above is/are correct?",["I and II only","I and III only","II and III only","III only"],"C",GEO,PHY,"Earth Motions & Geographical Coordinates","Date line and rotation","3-Statement Combination","I is false: the Prime Meridian is $0^\\circ$ and the Date Line is near $180^\\circ$.\nII: the place to the west of the line is one day ahead (true).\nIII: $360^\\circ/24$ h $=15^\\circ$ per hour (true).\nAnswer: (c)")
g(112,"The Earth's equatorial region bulges outward, but the Earth flattens slightly towards the polar regions due to the:",["Presence of a large oceanic mass in the southern hemisphere","Earth's rotational force","Earth's revolution","Greater gravitational force at the equator"],"B",GEO,PHY,"Earth Motions & Geographical Coordinates","Shape of the Earth","Single MCQ","Rotation produces a centrifugal effect that is greatest at the equator, so the equator bulges and the poles flatten.\nAnswer: (b)")
g(113,"In the southern hemisphere, trade winds blow from:",["North-East to South-West","South-East to North-West","North-West to South-East","South-West to North-East"],"B",GEO,PHY,"Atmospheric Circulation","Direction of trade winds","Single MCQ","Trade winds blow towards the equator, deflected to the left in the southern hemisphere, so they are the south-east trades blowing from the south-east to the north-west.\nAnswer: (b)")
g(114,"Consider the following statements regarding the structure of the atmosphere:\nI. The average height of the troposphere is higher nearer the poles than at the equator.\nII. The mesosphere contains the ozone layer.\nIII. Radio waves transmitted from the Earth are reflected to the Earth by the ionosphere.\nIV. In the mesosphere, temperature decreases with an increase in altitude.\nWhich of the statements given above are correct?",["I and II only","II and III only","III and IV only","I, II, III and IV"],"C",GEO,PHY,"Climatology","Layers of the atmosphere","4-Statement Combination","I is false: the troposphere is about 18 km at the equator and 8 km at the poles.\nII is false: the ozone layer is in the stratosphere.\nIII and IV are true.\nAnswer: (c)")
g(115,"Consider the following oceanic currents:\nI. Oyashio\nII. Canaries\nIII. Labrador\nIV. Kuroshio\nV. Benguela\nVI. Alaska\nVII. Humboldt\nHow many of the above are Pacific Ocean currents?",["One","Two","Three","Four"],"D",GEO,PHY,"Oceanography","Ocean currents by ocean basin","Statement Count","M","Pacific: Oyashio, Kuroshio, Alaska and Humboldt (four).\nAtlantic: Canaries, Labrador and Benguela.\nAnswer: (d)")
g(116,"Consider the following:\nI. Abrasion\nII. Attrition\nIII. Hydraulic action\nIV. Solution\nWhich of the above are the main types of river erosion?",["I, II and III only","I, III and IV only","II and IV only","I, II, III and IV"],"D",GEO,PHY,"Geomorphology & Earth Surface Processes","Types of river erosion","4-Statement Combination","The main processes of river erosion are hydraulic action, abrasion (corrasion), attrition and solution (corrosion).\nAll four.\nAnswer: (d)")
g(117,"A prolonged period of inadequate rainfall marked with mal-distribution of the same over time and space is known as:",["Agricultural drought","Hydrological drought","Ecological drought","Meteorological drought"],"D",GEO,PHY,"Natural Hazards","Types of drought","Single MCQ","A meteorological drought is defined by a prolonged period of deficient and unevenly distributed rainfall.\nAgricultural, hydrological and ecological droughts describe the impacts on crops, water and ecosystems.\nAnswer: (d)")
g(118,"Which group of landlocked states shares a boundary with Madhya Pradesh?",["Rajasthan, Uttar Pradesh, Chhattisgarh, Maharashtra and Gujarat only","Rajasthan, Uttar Pradesh, Jharkhand and Chhattisgarh only","Rajasthan, Uttar Pradesh, Jharkhand, Chhattisgarh, Maharashtra and Gujarat","Rajasthan, Uttar Pradesh and Chhattisgarh only"],"D",GEO,IND,"Political Geography of India","States bordering Madhya Pradesh","Single MCQ","Madhya Pradesh borders Rajasthan, Uttar Pradesh, Chhattisgarh, Maharashtra and Gujarat; it does not border Jharkhand.\nMaharashtra and Gujarat are coastal, so the landlocked neighbours are Rajasthan, Uttar Pradesh and Chhattisgarh.\nAnswer: (d)")
g(119,"Consider the following statements regarding the nature of rocks:\nI. Rocks are aggregates of one or more minerals.\nII. Granite is softer than soapstone.\nIII. Gabbro is black and quartzite can be milky white.\nIV. Sedimentary rocks are related to foliation.\nWhich of the statements given above are not correct?",["I and II","I and III","II and IV","II and III"],"C",GEO,PHY,"Rocks & Minerals","Properties of rocks","4-Statement Combination","I and III are correct.\nII is wrong: granite is hard while soapstone is very soft.\nIV is wrong: foliation is a feature of metamorphic rocks.\nAnswer: (c)")
g(120,"The 'Agricultural Population Density' is referred to as the ratio of the:",["Total population to Net cultivable land","Agricultural population to Gross cropped area","Total population to Total reported land","Total agricultural population to Net cultivable land"],"D",GEO,"Human Geography","Population Geography","Measures of population density","Single MCQ","Agricultural density is the number of agricultural workers or the agricultural population per unit of net cultivated (cultivable) area.\nAnswer: (d)")
if __name__=="__main__": print(len(G))
